<?php
/** Proof — members (spec "Proof", 5): Priya rates her own solved ticket from the ticket page; Marco's rating_submit on it → 403; ratings-list for Lena with the CSAT percentage, for Marco IT's only, for Priya 403 "You may not see reports."; the CSV. */
require __DIR__ . '/lib.php';
$W = world();
marco_in_general();
$priya = as_member(26); $marco = as_member(27); $lena = as_member(28);
$t = (int) act($priya, '/tickets/save.php', ['subject' => 'SMOKE Priya rates', 'body' => 'x'])[1]['record_id'];
q('UPDATE tickets SET queue_id = :q, assignee_member_id = 27 WHERE id = :t', ['q' => $W['it'], 't' => $t]);
act($marco, '/tickets/reply.php', ['ticket' => $t, 'body' => 'Done.', 'then_status' => 'solved', 'resolution_code' => 'resolved']);
echo "1. Priya rates from her ticket page\n";
$body = page($priya, '/tickets/' . $t)['body'];
ok(str_contains($body, 'id="ticket-rating-form"') && str_contains($body, 'id="ticket-rating-good"'), 'the rating block on her solved ticket');
ok(!str_contains(page($marco, '/tickets/' . $t)['body'], 'id="ticket-rating-form"'), 'not on Marco\'s view of it');
[$c, $b] = act($marco, '/ratings/save.php', ['ticket' => $t, 'score' => 5]);
ok($c === 403 && msg($b) === 'Only the requester rates a ticket.', 'Marco\'s rating_submit on it: 403');
$since = last_activity_id();
[$c, $b] = act($priya, '/ratings/save.php', ['ticket' => $t, 'score' => 5, 'comment' => 'Quick, thanks']);
ok($c === 200 && (int) rating_row($t)['score'] === 5 && rating_row($t)['responded_at'] !== null && count(activity('rating.submit', $since)) === 1 && (int) one("SELECT count(*) FROM notifications WHERE member_id = 27 AND ticket_id = :t AND kind = 'rated'", ['t' => $t]) === 1, 'rating_submit: written, logged, Marco told (the bell)');
[$c, $b] = act($priya, '/ratings/save.php', ['ticket' => $t, 'score' => 1]);
ok($c === 422 && msg($b) === 'Thank you — already received.', 'a second: already received');
ok(str_contains(page($priya, '/tickets/' . $t)['body'], 'id="ticket-rating-done"'), 'her page says so');
$fac = (int) act($lena, '/tickets/save.php', ['subject' => 'SMOKE Facilities rated', 'body' => 'x', 'queue' => $W['fac'], 'requester' => $W['jo']])[1]['record_id'];
act($lena, '/tickets/transition.php', ['ticket' => $fac, 'status' => 'open']);
act($lena, '/tickets/transition.php', ['ticket' => $fac, 'status' => 'solved', 'resolution_code' => 'resolved']);
q("INSERT INTO satisfaction_ratings (ticket_id, requester_id, score, bad_reason, comment, responded_at, token_hash, expires_at) VALUES (:t, :r, 1, 'Not resolved', 'nope', now(), md5(random()::text) || md5(random()::text), now() + interval '1 day')", ['t' => $fac, 'r' => $W['jo']]);
echo "2. The ratings list\n";
[$c, $d] = screen($lena, '/ratings/');
$ids = array_map(fn ($r) => $r['ticket_id'], $d['ratings']);
ok($c === 200 && in_array($t, $ids, true) && in_array($fac, $ids, true) && $d['csat_percent'] !== null && $d['ratings'][0]['is_bad'] === true, 'Lena (view_all + reports.view): every rating, bad ones first, a CSAT percentage (' . $d['csat_percent'] . '%)');
[$c, $d] = screen($marco, '/ratings/');
$ids = array_map(fn ($r) => $r['ticket_id'], $d['ratings']);
ok($c === 200 && in_array($t, $ids, true) && !in_array($fac, $ids, true), 'Marco (IT): IT\'s ratings only');
$r = page($priya, '/ratings/');
ok($r['code'] === 403 && str_contains($r['body'], 'You may not see reports.'), 'Priya: 403 "You may not see reports."');
[$c, $d] = screen($lena, '/ratings/?score=bad');
ok(count(array_filter($d['ratings'], fn ($r) => !$r['is_bad'])) === 0 && count($d['ratings']) >= 1, 'the bad filter');
$body = page($lena, '/ratings/')['body'];
ok(str_contains($body, 'id="ratings-csat"') && str_contains($body, 'id="rating-row-') && str_contains($body, 'Not resolved'), 'the page: the CSAT badge and the ledger rows');
$since = last_activity_id();
$r = req('GET', '/ratings/?format=csv', ['jar' => $lena]);
ok($r['code'] === 200 && preg_match('/^Content-Type: text\/csv/mi', $r['headers']) === 1 && str_contains($r['body'], 'responded_at,ticket,subject') && str_contains($r['body'], 'Quick, thanks') && count(activity('report.export', $since)) === 1, 'the CSV, logged as report.export');
echo "3. The agent and the registry\n";
$reg = json_decode(file_get_contents(dirname(__DIR__, 3) . '/mcp/action_registry.json'), true);
$find = function (string $key) use ($reg) { foreach ((array) $reg['actions'] as $k => $a) { if (is_array($a) && ($a['key'] ?? $k) === $key) { return $a; } } return null; };
ok(str_contains(json_encode($find('survey_send')), 'external_send') && str_contains(json_encode($find('csat_settings_save')), 'other'), 'the registry marks survey_send external_send and csat_settings_save other (the kernel pauses an agent by action)');
finish();
